INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('ensayometro-felicitar', 'Campaña Ensayómetro — ensayometro-felicitar', $asunto$🎉 ¡Tu constancia se nota en el Ensayómetro!$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://adorapp.net.ar/ensayo-banner-felicitar.png" width="600" alt="Ministerio de Adoración — Tu constancia se nota" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Queremos felicitarte de corazón. 🎉 Tu dedicación no pasa desapercibida: <b>venís usando tu Ensayómetro</b>, preparando cada canción antes de subir a ministrar. Y se siente — cuando llega el servicio, <b>fluís con paz y seguridad</b>.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«¿Has visto hombre solícito en su trabajo? Delante de los reyes estará.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Proverbios 22:29</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;"><b>Tu diligencia te distingue.</b> Seguí así: sumá las próximas canciones del orden, marcá tus pasadas y, si todavía no lo probaste, activá el metrónomo para pulir el tempo. Cada ensayo tuyo es <b>una ofrenda preparada con excelencia</b> para el Rey.</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">¡Gracias por darle lo mejor! 🙌</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Abrir mi Ensayómetro</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Ministerio de Adoración — Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Queremos felicitarte de corazon. Tu dedicacion no pasa desapercibida: venis usando tu Ensayometro, preparando cada cancion antes de subir a ministrar. Y se siente: cuando llega el servicio, fluis con paz y seguridad.

"¿Has visto hombre solícito en su trabajo? Delante de los reyes estará." (Proverbios 22:29)

Tu diligencia te distingue. Segui asi: suma las proximas canciones del orden, marca tus pasadas y, si todavia no lo probaste, activa el metronomo para pulir el tempo. Cada ensayo tuyo es una ofrenda preparada con excelencia para el Rey. Gracias por darle lo mejor!

Abrir mi Ensayómetro: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
ON CONFLICT (slug) DO UPDATE SET descripcion=EXCLUDED.descripcion, asunto=EXCLUDED.asunto, from_label=EXCLUDED.from_label, activo=EXCLUDED.activo, color_acento=EXCLUDED.color_acento, mostrar_logo=EXCLUDED.mostrar_logo, body_html=EXCLUDED.body_html, body_text=EXCLUDED.body_text, cuerpo_html=NULL, updated_at=now();

INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('ensayometro-estimular', 'Campaña Ensayómetro — ensayometro-estimular', $asunto$🙌 Ya diste el primer paso — demos el segundo$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://adorapp.net.ar/ensayo-banner-estimular.png" width="600" alt="Ministerio de Adoración — Ya diste el primer paso" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Vimos algo que nos alegró: <b>activaste la alarma de ensayo</b>. 🙌 Eso dice mucho de tu corazón — y de tus ganas de prepararte bien. Ahora viene lo mejor: <b>tu primer ensayo</b>.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«Sed hacedores de la palabra, y no tan solamente oidores.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Santiago 1:22</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">Es más simple de lo que imaginás: entrá a tu Ensayómetro, abrí una canción del próximo orden y marcá una pasada. <b>En tres toques ya estás practicando</b>, con los acordes en tu tono y la letra a mano. El paso más difícil —decidirte— <b>ya lo diste</b>. Demos juntos el segundo. 💪</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Tu preparación va a marcar la diferencia este fin de semana.</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Empezar mi primer ensayo</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Ministerio de Adoración — Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Vimos algo que nos alegro: activaste la alarma de ensayo. Eso dice mucho de tu corazon, y de tus ganas de prepararte bien. Ahora viene lo mejor: tu primer ensayo.

"Sed hacedores de la palabra, y no tan solamente oidores." (Santiago 1:22)

Es mas simple de lo que imaginas: entra a tu Ensayometro, abri una cancion del proximo orden y marca una pasada. En tres toques ya estas practicando, con los acordes en tu tono y la letra a mano. El paso mas dificil, decidirte, ya lo diste. Demos juntos el segundo. Tu preparacion va a marcar la diferencia este fin de semana.

Empezar mi primer ensayo: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
ON CONFLICT (slug) DO UPDATE SET descripcion=EXCLUDED.descripcion, asunto=EXCLUDED.asunto, from_label=EXCLUDED.from_label, activo=EXCLUDED.activo, color_acento=EXCLUDED.color_acento, mostrar_logo=EXCLUDED.mostrar_logo, body_html=EXCLUDED.body_html, body_text=EXCLUDED.body_text, cuerpo_html=NULL, updated_at=now();

INSERT INTO public.email_templates (slug, descripcion, asunto, from_label, activo, color_acento, mostrar_logo, body_html, body_text)
VALUES ('ensayometro-invitar', 'Campaña Ensayómetro — ensayometro-invitar', $asunto$🎸 Descubrí tu Ensayómetro personal$asunto$, 'adorapp', true, '#d8b23f', false, $body$<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#ece4d2;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ece4d2;"><tr><td align="center" style="padding:22px 10px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#fbf8f1;border-radius:16px;overflow:hidden;border:1px solid #e6dcc3;"><tr><td style="padding:0;line-height:0;"><img src="https://adorapp.net.ar/ensayo-banner-invitar.png" width="600" alt="Ministerio de Adoración — Descubrí tu Ensayómetro" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></td></tr><tr><td style="padding:28px 30px 26px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#3a342b;"><p style="margin:0 0 16px;font-size:17px;color:#2c2620;">Hola <b style="color:#1d1813;">{{nombre}}</b>,</p><p style="margin:0 0 15px;font-size:16px;line-height:1.62;">Queremos invitarte a conocer <b>una herramienta que te está esperando</b> dentro de AdorAPP: tu <b>Ensayómetro</b> personal. 🎸</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0 18px;"><tr><td style="background:#f6edd2;border-left:3px solid #d8b23f;border-radius:0 10px 10px 0;padding:14px 16px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td valign="top" style="padding-right:12px;"><img src="https://adorapp.net.ar/ensayo-biblia.png" width="26" height="26" alt="" style="display:block;border:0;"></td><td style="font-size:15.5px;line-height:1.5;color:#4a4335;font-style:italic;">«Cantadle cántico nuevo; hacedlo bien, tañendo con júbilo.»<br><span style="font-style:normal;font-weight:700;font-size:13px;color:#b8860b;letter-spacing:.3px;">Salmo 33:3</span></td></tr></table></td></tr></table><p style="margin:0 0 15px;font-size:15.5px;line-height:1.62;">«Hacedlo bien»: la Palabra misma nos invita a la excelencia, y <b>el Ensayómetro es tu aliado</b> para alcanzarla. Es tu espacio para practicar cada canción del orden —con los acordes en tu tono, la letra, y hasta un metrónomo— y saber de un vistazo cuán listo estás para el servicio. Se termina el llegar con dudas: <b>llegás con paz</b>.</p><p style="margin:0 0 20px;font-size:15.5px;line-height:1.62;">Probalo una vez. Va a cambiar tu forma de prepararte. ✨</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:12px;background:#d8b23f;"><a href="https://adorapp.net.ar" style="display:inline-block;padding:13px 28px;font-size:15px;font-weight:700;color:#2a2206;text-decoration:none;border-radius:12px;">Conocer mi Ensayómetro</a></td></tr></table><p style="margin:24px 0 0;padding-top:16px;border-top:1px solid #ece3cf;font-size:13.5px;color:#6f6552;line-height:1.6;">¡Bendiciones!<br><b style="color:#5a5140;">Pastores de Adoración CAF</b></p></td></tr></table><p style="margin:14px 0 0;font-family:Arial,sans-serif;font-size:11px;color:#a79e8b;">AdorAPP · Ministerio de Adoración — Adoración CAF · adorapp.net.ar</p></td></tr></table></body></html>$body$, $txt$Hola {{nombre}},

Queremos invitarte a conocer una herramienta que te esta esperando dentro de AdorAPP: tu Ensayometro personal.

"Cantadle cántico nuevo; hacedlo bien, tañendo con júbilo." (Salmo 33:3)

Hacedlo bien: la Palabra misma nos invita a la excelencia, y el Ensayometro es tu aliado para alcanzarla. Es tu espacio para practicar cada cancion del orden (con los acordes en tu tono, la letra y hasta un metronomo) y saber de un vistazo cuan listo estas para el servicio. Se termina el llegar con dudas: llegas con paz. Probalo una vez. Va a cambiar tu forma de prepararte.

Conocer mi Ensayómetro: https://adorapp.net.ar

Bendiciones!
Pastores de Adoracion CAF

AdorAPP - Adoracion CAF · adorapp.net.ar$txt$)
